-- Phase 5 initial schema. All identifiers are UUIDs generated by the application.
-- Auth tokens are stored only as SHA-256 hashes; plaintext never reaches Postgres.

CREATE TABLE players (
  id            uuid PRIMARY KEY,
  display_name  varchar(18) NOT NULL,
  avatar        varchar(16) NOT NULL DEFAULT 'fox',
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz
);

CREATE INDEX players_name_lower_idx ON players (lower(display_name));

CREATE TABLE auth_sessions (
  id                  uuid PRIMARY KEY,
  player_id           uuid NOT NULL REFERENCES players(id) ON DELETE CASCADE,
  token_hash          char(64) NOT NULL UNIQUE,
  previous_token_hash char(64),
  previous_valid_until timestamptz,
  created_at          timestamptz NOT NULL DEFAULT now(),
  last_used_at        timestamptz NOT NULL DEFAULT now(),
  expires_at          timestamptz NOT NULL,
  revoked_at          timestamptz,
  rotated_from        uuid,
  CHECK (expires_at > created_at)
);

CREATE INDEX auth_sessions_player_idx ON auth_sessions (player_id);
CREATE INDEX auth_sessions_active_idx ON auth_sessions (player_id) WHERE revoked_at IS NULL;
CREATE UNIQUE INDEX auth_sessions_previous_hash_idx ON auth_sessions (previous_token_hash)
  WHERE previous_token_hash IS NOT NULL;

CREATE TABLE matches (
  id                uuid PRIMARY KEY,
  finalization_key  text NOT NULL UNIQUE,
  room_code         varchar(5) NOT NULL,
  rounds            integer NOT NULL CHECK (rounds BETWEEN 1 AND 10),
  ended_at          timestamptz NOT NULL DEFAULT now(),
  created_at        timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX matches_ended_at_idx ON matches (ended_at DESC);

CREATE TABLE match_players (
  id              bigserial PRIMARY KEY,
  match_id        uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  player_id       uuid REFERENCES players(id) ON DELETE SET NULL,
  display_name    varchar(18) NOT NULL,
  avatar          varchar(16) NOT NULL,
  score           integer NOT NULL CHECK (score >= 0),
  rank            integer NOT NULL CHECK (rank >= 1),
  guesses         integer NOT NULL DEFAULT 0 CHECK (guesses >= 0),
  correct_guesses integer NOT NULL DEFAULT 0 CHECK (correct_guesses >= 0),
  won             boolean NOT NULL DEFAULT false,
  UNIQUE (match_id, display_name, rank)
);

CREATE INDEX match_players_match_idx ON match_players (match_id);
CREATE INDEX match_players_player_idx ON match_players (player_id);
CREATE UNIQUE INDEX match_players_one_row_per_player_idx ON match_players (match_id, player_id)
  WHERE player_id IS NOT NULL;

CREATE TABLE player_stats (
  player_id       uuid PRIMARY KEY REFERENCES players(id) ON DELETE CASCADE,
  games_played    integer NOT NULL DEFAULT 0 CHECK (games_played >= 0),
  games_won       integer NOT NULL DEFAULT 0 CHECK (games_won >= 0),
  total_score     bigint NOT NULL DEFAULT 0 CHECK (total_score >= 0),
  guesses         integer NOT NULL DEFAULT 0 CHECK (guesses >= 0),
  correct_guesses integer NOT NULL DEFAULT 0 CHECK (correct_guesses >= 0),
  updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX player_stats_leaderboard_idx ON player_stats (total_score DESC, games_won DESC, games_played ASC);

CREATE TABLE word_lists (
  player_id  uuid PRIMARY KEY REFERENCES players(id) ON DELETE CASCADE,
  categories jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (jsonb_typeof(categories) = 'array')
);

CREATE TABLE reports (
  id            uuid PRIMARY KEY,
  room_code     varchar(5) NOT NULL,
  reporter_id   uuid REFERENCES players(id) ON DELETE SET NULL,
  target_id     uuid REFERENCES players(id) ON DELETE SET NULL,
  reporter_name varchar(18) NOT NULL,
  target_name   varchar(18) NOT NULL,
  reason        varchar(200) NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX reports_created_idx ON reports (created_at DESC);
CREATE INDEX reports_target_idx ON reports (target_id, created_at DESC);
CREATE INDEX reports_room_idx ON reports (room_code, created_at DESC);

-- room_code NULL means a global ban. Bans are persisted so they survive restarts
-- and deployments; room bans apply to one room instance's code.
CREATE TABLE bans (
  id         uuid PRIMARY KEY,
  player_id  uuid NOT NULL REFERENCES players(id) ON DELETE CASCADE,
  room_code  varchar(5),
  banned_by  uuid REFERENCES players(id) ON DELETE SET NULL,
  reason     varchar(200),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz,
  revoked_at timestamptz,
  UNIQUE NULLS NOT DISTINCT (player_id, room_code)
);

CREATE INDEX bans_active_idx ON bans (player_id) WHERE revoked_at IS NULL;

CREATE TABLE moderation_settings (
  key        text PRIMARY KEY,
  value      jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO moderation_settings (key, value) VALUES
  ('chat', '{"windowMs": 200, "max": 5}'),
  ('draw', '{"windowMs": 1000, "max": 120}'),
  ('report', '{"cooldownMs": 60000}'),
  ('auth', '{"windowMs": 60000, "max": 20}')
ON CONFLICT (key) DO NOTHING;
